"use client"

// Adapted from LocalMode UI (MIT) — apps/ui/registry/localmode/artifacts/artifact/artifact.tsx

import * as React from "react"
import { Download, RefreshCw, X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet"
import { cn } from "@/lib/utils"
import { CopyButton } from "@/components/ui/copy-button"

export type ArtifactAction = {
  id: string
  label: string
  icon?: React.ReactNode
  onSelect: () => void
}

export type ArtifactPanelProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  title: string
  description?: string
  content?: string
  fileName?: string
  mimeType?: string
  actions?: ArtifactAction[]
  onRefresh?: () => void
  children?: React.ReactNode
  className?: string
}

function useNarrow() {
  const [narrow, setNarrow] = React.useState(false)
  React.useEffect(() => {
    const query = window.matchMedia("(max-width: 639px)")
    const apply = () => setNarrow(query.matches)
    apply()
    query.addEventListener("change", apply)
    return () => query.removeEventListener("change", apply)
  }, [])
  return narrow
}

export function downloadArtifact(content: string, fileName: string, mimeType = "text/plain") {
  const blob = new Blob([content], { type: mimeType })
  const url = URL.createObjectURL(blob)
  const link = document.createElement("a")
  link.href = url
  link.download = fileName
  link.click()
  URL.revokeObjectURL(url)
}

function Toolbar({
  title,
  description,
  content,
  fileName,
  mimeType,
  actions,
  onRefresh,
  onClose,
}: ArtifactPanelProps & { onClose: () => void }) {
  return (
    <div className="flex min-w-0 flex-col gap-2 border-b border-border px-3 py-2">
      <div className="flex items-start gap-2">
        <div className="min-w-0 flex-1">
          <p className="truncate font-medium text-foreground">{title}</p>
          {description ? <p className="truncate text-xs text-muted-foreground">{description}</p> : null}
        </div>
        <div className="flex shrink-0 items-center gap-1">
          {content ? <CopyButton value={content} iconOnly label="Copy" /> : null}
          {content && fileName ? (
            <Button type="button" size="icon-sm" variant="ghost" aria-label="Download" onClick={() => downloadArtifact(content, fileName, mimeType)}>
              <Download data-icon="inline-start" />
            </Button>
          ) : null}
          {onRefresh ? (
            <Button type="button" size="icon-sm" variant="ghost" aria-label="Refresh" onClick={onRefresh}>
              <RefreshCw data-icon="inline-start" />
            </Button>
          ) : null}
          {actions?.map((action) => (
            <Button key={action.id} type="button" size="sm" variant="ghost" aria-label={action.label} onClick={action.onSelect}>
              {action.icon}
              <span className="sr-only">{action.label}</span>
            </Button>
          ))}
          <Button type="button" size="icon-sm" variant="ghost" aria-label="Close" onClick={onClose}>
            <X data-icon="inline-start" />
          </Button>
        </div>
      </div>
    </div>
  )
}

export function ArtifactPanel(props: ArtifactPanelProps) {
  const { open: openProp, defaultOpen = false, onOpenChange, children, className, title } = props
  const [internal, setInternal] = React.useState(defaultOpen)
  const open = openProp ?? internal
  const narrow = useNarrow()
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setInternal(next)
    onOpenChange?.(next)
  }

  const body = (
    <div className="min-h-0 flex-1 overflow-auto p-3 text-sm">
      {children ?? (props.content ? <pre className="overflow-auto font-mono text-xs">{props.content}</pre> : null)}
    </div>
  )

  if (!open) return null

  if (narrow) {
    return (
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent className={cn("flex w-full flex-col gap-0 p-0 sm:max-w-md", className)} onKeyDown={(event) => event.key === "Escape" && setOpen(false)}>
          <SheetHeader className="sr-only">
            <SheetTitle>{title}</SheetTitle>
          </SheetHeader>
          <Toolbar {...props} onClose={() => setOpen(false)} />
          {body}
        </SheetContent>
      </Sheet>
    )
  }

  return (
    <aside
      className={cn("flex min-h-64 w-full min-w-80 flex-col rounded-xl border border-border bg-card", className)}
      onKeyDown={(event) => {
        if (event.key === "Escape") setOpen(false)
      }}
    >
      <Toolbar {...props} onClose={() => setOpen(false)} />
      {body}
    </aside>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion, type TargetAndTransition, type Transition } from "motion/react"
import { CircleAlert, Copy } from "lucide-react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"
import { useCopyFeedback } from "@/hooks/use-copy-feedback"

export type CopyButtonClassNames = {
  root?: string
  icon?: string
  label?: string
}

export type CopyButtonProps = {
  value: string
  label?: string
  copiedLabel?: string
  failedLabel?: string
  className?: string
  classNames?: CopyButtonClassNames
  iconOnly?: boolean
  variant?: "outline" | "plain"
  disabled?: boolean
  onCopied?: () => void
}

const settle = { type: "spring", visualDuration: 0.5, bounce: 0.06 } as const
const enter = { duration: 0.36, ease: [...motionPresets.ease.enter] } as const
const instant = { duration: motionPresets.duration.instant } as const
const soft = `blur(${motionPresets.blur.soft}px)`
const rest: TargetAndTransition = { opacity: 1, y: 0, scale: 1, filter: "blur(0px)" }
const fadeIn: TargetAndTransition = { ...rest, opacity: 0 }
const fadeOut: TargetAndTransition = { opacity: 0, transition: instant }
const iconIn: TargetAndTransition = { opacity: 0, scale: 0.6, filter: soft }
const iconOut: TargetAndTransition = { opacity: 0, scale: 0.6, filter: soft, transition: { duration: 0.24, ease: [...motionPresets.ease.standard] } }
const iconEnter: Transition = { scale: settle, opacity: { ...enter, delay: 0.03 }, filter: { ...enter, delay: 0.03 } }
const glyphIn: TargetAndTransition = { opacity: 0, y: 4, filter: soft }
const glyphOut: TargetAndTransition = { opacity: 0, y: -3, filter: soft, transition: { duration: 0.2, ease: [...motionPresets.ease.standard] } }

function DrawnCheck({ reduced }: { reduced: boolean }) {
  return (
    <svg width={16} height={16} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <motion.path
        d="M4 12l5 5L20 6"
        initial={reduced ? false : { pathLength: 0, opacity: 0 }}
        animate={{ pathLength: 1, opacity: 1 }}
        transition={{
          pathLength: { duration: 0.5, ease: [...motionPresets.ease.standard], delay: 0.05 },
          opacity: { duration: 0.01, delay: 0.05 },
        }}
      />
    </svg>
  )
}

type Glyph = { id: string; char: string; order: number }
const toGlyphs = (chars: string[], seq: number): Glyph[] => chars.map((char, order) => ({ id: `${seq}:${order}`, char, order }))

function useGlyphs(text: string) {
  const [state, setState] = React.useState(() => ({ text, seq: 0, glyphs: toGlyphs([...text], 0) }))
  if (state.text === text) return state.glyphs
  const prev = [...state.text]
  const next = [...text]
  let start = 0
  let end = 0
  while (start < prev.length && start < next.length && prev[start] === next[start]) start++
  while (end < prev.length - start && end < next.length - start && prev[prev.length - 1 - end] === next[next.length - 1 - end]) end++
  if (start < 2) start = 0
  if (end < 2) end = 0
  const seq = state.seq + 1
  const glyphs = [
    ...state.glyphs.slice(0, start),
    ...toGlyphs(next.slice(start, next.length - end), seq),
    ...state.glyphs.slice(state.glyphs.length - end),
  ]
  setState({ text, seq, glyphs })
  return glyphs
}

function MorphText({ text, reduced }: { text: string; reduced: boolean }) {
  const glyphs = useGlyphs(text)
  return (
    <span className="relative inline-flex justify-self-start whitespace-pre">
      <AnimatePresence mode="popLayout" initial={false}>
        {glyphs.map((glyph) => (
          <motion.span
            key={glyph.id}
            className="inline-block"
            layout={reduced ? false : "position"}
            layoutDependency={text}
            initial={reduced ? fadeIn : glyphIn}
            animate={rest}
            exit={reduced ? fadeOut : glyphOut}
            transition={reduced ? instant : { ...enter, delay: Math.min(glyph.order * 0.02, 0.12), layout: settle }}
          >
            {glyph.char === " " ? "\u00a0" : glyph.char}
          </motion.span>
        ))}
      </AnimatePresence>
    </span>
  )
}

export function CopyButton({
  value,
  label = "Copy",
  copiedLabel = "Copied",
  failedLabel = "Failed",
  className,
  classNames,
  iconOnly = false,
  variant = "outline",
  disabled,
  onCopied,
}: CopyButtonProps) {
  const { state, copy } = useCopyFeedback()
  const reduced = useReducedMotion() ?? false
  const text = state === "copied" ? copiedLabel : state === "error" ? failedLabel : label

  async function handleCopy() {
    if (await copy(value)) onCopied?.()
  }

  return (
    <>
      <button
        type="button"
        data-slot="copy-button"
        data-copy-state={state}
        className={cn(
          "inline-flex max-w-full min-h-8 items-center justify-center gap-2 rounded-lg border border-border bg-background px-3 text-sm font-medium text-foreground transition-colors hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:opacity-50 motion-reduce:transition-none",
          iconOnly && "size-8 px-0",
          variant === "plain" && "border-transparent bg-transparent text-muted-foreground hover:bg-muted",
          className,
          classNames?.root,
        )}
        onClick={() => void handleCopy()}
        aria-label={label}
        disabled={disabled}
      >
        <span data-slot="copy-button-icon" className={cn("relative grid size-4 shrink-0", classNames?.icon)} aria-hidden="true">
          <AnimatePresence initial={false}>
            <motion.span
              key={state}
              data-state={state}
              className={cn(
                "absolute inset-0 grid place-items-center",
                state === "copied" && "text-primary",
                state === "error" && "text-destructive",
              )}
              initial={reduced ? fadeIn : iconIn}
              animate={rest}
              exit={reduced ? fadeOut : iconOut}
              transition={reduced ? instant : iconEnter}
            >
              {state === "copied" ? <DrawnCheck reduced={reduced} /> : state === "error" ? <CircleAlert size={16} strokeWidth={1.8} /> : <Copy size={16} strokeWidth={1.8} />}
            </motion.span>
          </AnimatePresence>
        </span>
        {iconOnly ? null : (
          <span data-slot="copy-button-label" className={cn("grid min-w-0 overflow-x-clip text-left whitespace-nowrap", classNames?.label)} aria-hidden="true">
            <span className="invisible col-start-1 row-start-1">{label}</span>
            <span className="invisible col-start-1 row-start-1">{copiedLabel}</span>
            <span className="invisible col-start-1 row-start-1">{failedLabel}</span>
            <span className="col-start-1 row-start-1">
              <MorphText text={text} reduced={reduced} />
            </span>
          </span>
        )}
      </button>
      <span className="sr-only" role="status" aria-live="polite">
        {state === "idle" ? "" : state === "error" ? `${label}: Could not copy` : `${label}: ${copiedLabel}`}
      </span>
    </>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import { useCallback, useEffect, useRef, useState } from "react"

export type CopyFeedbackState = "idle" | "copied" | "error"

/** Clipboard state for actions that render their own button or menu. */
export function useCopyFeedback(duration = 1900) {
  const [state, setState] = useState<CopyFeedbackState>("idle")
  const [activeKey, setActiveKey] = useState<string | null>(null)
  const timeout = useRef<ReturnType<typeof setTimeout> | null>(null)

  const reset = useCallback(() => {
    if (timeout.current) clearTimeout(timeout.current)
    timeout.current = null
    setState("idle")
    setActiveKey(null)
  }, [])

  useEffect(
    () => () => {
      if (timeout.current) clearTimeout(timeout.current)
    },
    [],
  )

  const copy = useCallback(
    async (value: string, key = "default") => {
      if (timeout.current) clearTimeout(timeout.current)
      setActiveKey(key)
      try {
        await navigator.clipboard.writeText(value)
        setState("copied")
        timeout.current = setTimeout(reset, duration)
        return true
      } catch {
        setState("error")
        timeout.current = setTimeout(reset, duration)
        return false
      }
    },
    [duration, reset],
  )

  return { state, activeKey, copy, reset }
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
